import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as r,o as a,af as s}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const b=JSON.parse('{"title":"Codex Security","description":"","frontmatter":{},"headers":[],"relativePath":"products/ai-coding/codex/codex-security.md","filePath":"products/ai-coding/codex/codex-security.md","lastUpdated":1787107158000}'),o={name:"products/ai-coding/codex/codex-security.md"};function n(i,e,c,l,d,p){return a(),r("div",null,[...e[0]||(e[0]=[s(`<h1 id="codex-security" tabindex="-1">Codex Security <a class="header-anchor" href="#codex-security" aria-label="Permalink to &quot;Codex Security&quot;">​</a></h1><blockquote><p>A <strong>tutorial</strong> — run one read-only scan on a repo you own, then read the report. Codex Security is an application-security agent with <strong>three doors</strong>: desktop plugin, CLI/SDK, and Cloud. This page is the map and the first scan, not a copy of every official workflow.</p><p>Official landing: <a href="https://learn.chatgpt.com/codex/security" target="_blank" rel="noreferrer">learn.chatgpt.com/codex/security</a>. Docs: <a href="https://learn.chatgpt.com/docs/security" target="_blank" rel="noreferrer">Codex Security</a>.</p></blockquote><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Need</th><th>Requirement</th></tr></thead><tbody><tr><td>Permission</td><td>Scan <strong>only</strong> code you own or have authorization to assess</td></tr><tr><td>Account</td><td>Codex Security access. Best results: <a href="https://chatgpt.com/cyber" target="_blank" rel="noreferrer">Trusted Access for Cyber</a></td></tr><tr><td>Desktop plugin</td><td><a href="https://learn.chatgpt.com/docs/app" target="_blank" rel="noreferrer">ChatGPT desktop app</a> with Codex</td></tr><tr><td>CLI / SDK</td><td>Node for <code>npx</code>; optional TypeScript app</td></tr><tr><td>Cloud</td><td>A GitHub repo already visible in <a href="./codex-cloud.html">Codex Cloud</a></td></tr></tbody></table><p><strong>Learning objectives</strong>: tell the three doors apart; install the plugin or run the CLI help; complete one read-only first scan; know that Cloud Security is a research preview.</p><p><strong>Non-goals</strong>: writing exploit payloads; a full SARIF/CI cookbook (see official CI docs); agent sandbox theory (<a href="./codex-cli.html">CLI</a>).</p><h2 id="three-doors-one-scanner" tabindex="-1">Three doors, one scanner <a class="header-anchor" href="#three-doors-one-scanner" aria-label="Permalink to &quot;Three doors, one scanner&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Codex Security</span></span>
<span class="line"><span>├── Plugin          desktop workbench + CLI \`/plugins\`</span></span>
<span class="line"><span>│                   Scans · Findings · Repositories</span></span>
<span class="line"><span>├── CLI / SDK       @openai/codex-security</span></span>
<span class="line"><span>│                   local, bulk, CI, TypeScript</span></span>
<span class="line"><span>└── Cloud           research preview</span></span>
<span class="line"><span>                    connected GitHub repos via Codex Cloud</span></span></code></pre></div><p>The desktop <strong>Security</strong> workbench and the Codex CLI both use the <strong>Codex Security plugin</strong>. Cloud scans GitHub through Codex Cloud. Sandbox, approvals, and admin policy are still the <a href="https://learn.chatgpt.com/docs/agent-approvals-security" target="_blank" rel="noreferrer">agent security</a> model — Security does not replace them.</p><table tabindex="0"><thead><tr><th>Door</th><th>Use when</th><th>Start here</th></tr></thead><tbody><tr><td>Plugin</td><td>Interactive triage in the desktop app</td><td><a href="https://learn.chatgpt.com/docs/security/plugin" target="_blank" rel="noreferrer">Plugin quickstart</a></td></tr><tr><td>CLI / SDK</td><td>Repeatable local scans, bulk inventory, CI</td><td><a href="https://learn.chatgpt.com/docs/security/cli" target="_blank" rel="noreferrer">CLI quickstart</a> · <a href="https://learn.chatgpt.com/docs/security/sdk" target="_blank" rel="noreferrer">SDK</a></td></tr><tr><td>Cloud</td><td>Hosted scans of connected GitHub repos</td><td><a href="https://learn.chatgpt.com/docs/security/setup" target="_blank" rel="noreferrer">Cloud setup</a></td></tr></tbody></table><p>Install the plugin from ChatGPT: <a href="https://chatgpt.com/plugins/share/676aca3811d54fa7bcdef5255236b3c4" target="_blank" rel="noreferrer">plugin share link</a>.</p><h2 id="first-local-scan-plugin" tabindex="-1">First local scan (plugin) <a class="header-anchor" href="#first-local-scan-plugin" aria-label="Permalink to &quot;First local scan (plugin)&quot;">​</a></h2><p>Official first-scan path: <a href="https://learn.chatgpt.com/docs/security/plugin" target="_blank" rel="noreferrer">Plugin quickstart</a>. Quality default: <code>gpt-5.6-sol</code> with <code>xhigh</code> reasoning.</p><h3 id="desktop" tabindex="-1">Desktop <a class="header-anchor" href="#desktop" aria-label="Permalink to &quot;Desktop&quot;">​</a></h3><ol><li>Open Codex in the ChatGPT desktop app.</li><li><strong>Plugins</strong> → search <strong>Codex Security</strong> → install and enable.</li><li>Open <strong>Security</strong> in the sidebar. If it is missing, update the app and plugin.</li><li><strong>Scans → + Scan</strong>. Pick a repo or folder. Leave <strong>Deep scan</strong> off for the first run.</li><li>Start the scan. Review <strong>Findings</strong>, coverage, and <code>report.md</code>.</li></ol><p>Workbench panes: <strong>Scans</strong> (progress and saved results), <strong>Findings</strong> (issues and evidence), <strong>Repositories</strong> (history). Details: <a href="https://learn.chatgpt.com/docs/security/plugin/workbench" target="_blank" rel="noreferrer">Security workbench</a>.</p><h3 id="cli-session-via-the-plugin" tabindex="-1">CLI session via the plugin <a class="header-anchor" href="#cli-session-via-the-plugin" aria-label="Permalink to &quot;CLI session via the plugin&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/code/your-repo</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codex</span></span></code></pre></div><p>Then <code>/plugins</code> → install <strong>Codex Security</strong> → <code>/new</code>, and send:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Run a Codex Security scan on this repository.</span></span></code></pre></div><p>Keep the task running until it finishes. Read the terminal summary, then <code>report.md</code>. Approve any config change only after you read the exact patch.</p><h2 id="cli-and-sdk-package" tabindex="-1">CLI and SDK package <a class="header-anchor" href="#cli-and-sdk-package" aria-label="Permalink to &quot;CLI and SDK package&quot;">​</a></h2><p>Public package: <a href="https://github.com/openai/codex-security" target="_blank" rel="noreferrer"><code>@openai/codex-security</code></a>.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @openai/codex-security</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --help</span></span></code></pre></div><p>Use the same scanner across repos and over time: discover GitHub repos, resume bulk scans, track findings, record false-positive feedback, set a cost limit, or run in CI. The TypeScript SDK embeds scanning, progress, and cancel into a tool.</p><table tabindex="0"><thead><tr><th>Job</th><th>Official page</th></tr></thead><tbody><tr><td>First terminal scan</td><td><a href="https://learn.chatgpt.com/docs/security/cli" target="_blank" rel="noreferrer">CLI quickstart</a></td></tr><tr><td>Bulk / CSV inventory</td><td><a href="https://learn.chatgpt.com/docs/security/cli/bulk-scans" target="_blank" rel="noreferrer">Bulk scans</a></td></tr><tr><td>PR / MR in CI, SARIF</td><td><a href="https://learn.chatgpt.com/docs/security/cli/ci" target="_blank" rel="noreferrer">CLI in CI</a></td></tr><tr><td>Flags and exit codes</td><td><a href="https://learn.chatgpt.com/docs/security/cli/reference" target="_blank" rel="noreferrer">CLI reference</a></td></tr><tr><td>From application code</td><td><a href="https://learn.chatgpt.com/docs/security/sdk" target="_blank" rel="noreferrer">TypeScript SDK</a></td></tr></tbody></table><p>This is <strong>not</strong> the general <a href="https://learn.chatgpt.com/docs/codex-sdk" target="_blank" rel="noreferrer">Codex SDK</a> (<code>@openai/codex-sdk</code>). Use the Security SDK only for structured security findings.</p><h2 id="cloud-research-preview" tabindex="-1">Cloud (research preview) <a class="header-anchor" href="#cloud-research-preview" aria-label="Permalink to &quot;Cloud (research preview)&quot;">​</a></h2><p>Codex Security cloud scans connected GitHub repositories commit by commit. It builds a repo-specific threat model, validates high-signal issues in an isolated environment, then surfaces ranked findings with evidence and suggested patches.</p><p>If a repo is missing, confirm it is visible in your Codex Cloud workspace, or contact your OpenAI account team.</p><p>Threat-model edits: <a href="https://learn.chatgpt.com/docs/security/threat-model" target="_blank" rel="noreferrer">Improving the threat model</a>. PR reviews: <a href="https://learn.chatgpt.com/docs/security/security-review" target="_blank" rel="noreferrer">Security Review</a>.</p><h2 id="after-the-first-scan" tabindex="-1">After the first scan <a class="header-anchor" href="#after-the-first-scan" aria-label="Permalink to &quot;After the first scan&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Next</th><th>Official page</th></tr></thead><tbody><tr><td>Deep scan (slower, broader)</td><td><a href="https://learn.chatgpt.com/docs/security/plugin/deep-scans" target="_blank" rel="noreferrer">Deep scans</a></td></tr><tr><td>Review a PR / branch / patch</td><td><a href="https://learn.chatgpt.com/docs/security/plugin/code-changes" target="_blank" rel="noreferrer">Code changes</a></td></tr><tr><td>Triage an existing backlog</td><td><a href="https://learn.chatgpt.com/docs/security/plugin/triage-backlog" target="_blank" rel="noreferrer">Triage</a></td></tr><tr><td>Bounded fix + verify</td><td><a href="https://learn.chatgpt.com/docs/security/plugin/fix-findings" target="_blank" rel="noreferrer">Fix findings</a></td></tr><tr><td>Export / track</td><td><a href="https://learn.chatgpt.com/docs/security/plugin/export-findings" target="_blank" rel="noreferrer">Export findings</a></td></tr></tbody></table><p>A completed scan typically writes <code>report.md</code>, optional <code>findings/&lt;slug&gt;/</code> and <code>hardening/</code>, plus <code>scan-manifest.json</code>, <code>findings.json</code>, and <code>coverage.json</code>. Keep the directory together so links from <code>report.md</code> still resolve.</p><h2 id="common-pitfalls" tabindex="-1">Common pitfalls <a class="header-anchor" href="#common-pitfalls" aria-label="Permalink to &quot;Common pitfalls&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Pitfall</th><th>What happens</th><th>Do this instead</th></tr></thead><tbody><tr><td>Scanning a repo you do not own</td><td>Policy and legal problem</td><td>Stop. Assess only authorized code</td></tr><tr><td>Treating findings as proof</td><td>False positives still happen</td><td>Read evidence; Cloud/plugin validate, you still decide</td></tr><tr><td>Asking for a working exploit</td><td>Out of scope for this guide</td><td>Review official evidence; do not write exploit PoCs here</td></tr><tr><td>Mixing Security SDK with Codex SDK</td><td>Wrong package</td><td><code>@openai/codex-security</code> vs <code>@openai/codex-sdk</code></td></tr><tr><td>Skipping Trusted Access</td><td>Weaker scans</td><td><a href="https://chatgpt.com/cyber" target="_blank" rel="noreferrer">chatgpt.com/cyber</a> when you qualify</td></tr></tbody></table><h2 id="real-world-use" tabindex="-1">Real-world use <a class="header-anchor" href="#real-world-use" aria-label="Permalink to &quot;Real-world use&quot;">​</a></h2><p>Before a release, run a <strong>read-only</strong> plugin scan on <code>packages/api</code>. Accept one finding, ask for a bounded patch, and re-run the related test. Put CI on the Security CLI for pull-request diffs. Leave Cloud on for the GitHub org if your workspace has the research preview.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ol><li>Plugin first scan → <a href="https://learn.chatgpt.com/docs/security/plugin" target="_blank" rel="noreferrer">Plugin quickstart</a></li><li>Repeatable CLI → <a href="https://learn.chatgpt.com/docs/security/cli" target="_blank" rel="noreferrer">CLI quickstart</a></li><li>Hosted GitHub → <a href="https://learn.chatgpt.com/docs/security/setup" target="_blank" rel="noreferrer">Cloud setup</a></li><li>Agent sandbox (separate layer) → <a href="https://learn.chatgpt.com/docs/agent-approvals-security" target="_blank" rel="noreferrer">Agent approvals &amp; security</a></li></ol><h2 id="official-sources" tabindex="-1">Official sources <a class="header-anchor" href="#official-sources" aria-label="Permalink to &quot;Official sources&quot;">​</a></h2><ul><li><a href="https://learn.chatgpt.com/codex/security" target="_blank" rel="noreferrer">Codex Security (landing)</a></li><li><a href="https://learn.chatgpt.com/docs/security" target="_blank" rel="noreferrer">Codex Security (docs)</a></li><li><a href="https://learn.chatgpt.com/docs/security/plugin" target="_blank" rel="noreferrer">Plugin quickstart</a> · <a href="https://learn.chatgpt.com/docs/security/plugin/workbench" target="_blank" rel="noreferrer">Workbench</a></li><li><a href="https://learn.chatgpt.com/docs/security/cli" target="_blank" rel="noreferrer">CLI</a> · <a href="https://learn.chatgpt.com/docs/security/sdk" target="_blank" rel="noreferrer">SDK</a></li><li><a href="https://learn.chatgpt.com/docs/security/setup" target="_blank" rel="noreferrer">Cloud setup</a> · <a href="https://learn.chatgpt.com/docs/security/faq" target="_blank" rel="noreferrer">Cloud FAQ</a></li><li><a href="https://learn.chatgpt.com/docs/security/security-review" target="_blank" rel="noreferrer">Security Review</a></li><li><a href="https://github.com/openai/codex-security" target="_blank" rel="noreferrer">openai/codex-security</a></li></ul>`,42)])])}const k=t(o,[["render",n]]);export{b as __pageData,k as default};
